)=∂_r u_t(x,r).\", \"depends_on\": [\"D003\"], \"requires\": [], \"binders\": [{\"symbol\": \"x\", \"type\": \"point of V\"}, {\"symbol\": \"r\", \"type\": \"positive real\"}], \"objects\": [\"u_t\"]}}, {\"pointer\": \"spec.json#/definitions/4\", \"record\": {\"id\": \"D005\", \"symbol\": \"u_j\", \"type\": \"family indexed by j=1,...,n of functions V×(0,∞)→W\", \"definition\": \"u_j(x,r)=∂_{x_j}u(x,r), the coordinate derivative in the jth spatial direction.\", \"depends_on\": [\"D001\", \"D002\"], \"requires\": [], \"binders\": [{\"symbol\": \"j\", \"type\": \"integer with 1≤j≤n\"}, {\"symbol\": \"x\", \"type\": \"point of V\"}, {\"symbol\": \"r\", \"type\": \"positive real\"}], \"objects\": [\"u\", \"n\", \"V\", \"W\"]}}, {\"pointer\": \"spec.json#/definitions/5\", \"record\": {\"id\": \"D006\", \"symbol\": \"u_jj\", \"type\": \"family indexed by j=1,...,n of functions V×(0,∞)→W\", \"definition\": \"u_jj(x,r)=∂_{x_j}u_j(x,r).\", \"depends_on\": [\"D005\"], \"requires\": [], \"binders\": [{\"symbol\": \"j\", \"type\": \"integer with 1≤j≤n\"}, {\"symbol\": \"x\", \"type\": \"point of V\"}, {\"symbol\": \"r\", \"type\": \"positive real\"}], \"objects\": [\"u_j\", \"n\"]}}, {\"pointer\": \"spec.json#/definitions/6\", \"record\": {\"id\": \"D007\", \"symbol\": \"u_jt\", \"type\": \"family indexed by j=1,...,n of functions V×(0,∞)→W\", \"definition\": \"u_jt(x,r)=∂_{x_j}u_t(x,r). Commutation with ∂_r u_j is a claim to be proved, not part of this definition.\", \"depends_on\": [\"D003\", \"D005\"], \"requires\": [], \"binders\": [{\"symbol\": \"j\", \"type\": \"integer with 1≤j≤n\"}, {\"symbol\": \"x\", \"type\": \"point of V\"}, {\"symbol\": \"r\", \"type\": \"positive real\"}], \"objects\": [\"u_t\", \"n\"]}}, {\"pointer\": \"spec.json#/definitions/7\", \"record\": {\"id\": \"D008\", \"symbol\": \"Δu\", \"type\": \"function V×(0,∞)→W\", \"definition\": \"Δu(x,r)=sum_{j=1}^n u_jj(x,r), component by component. The gradient D_x u has columns u_j; its Frobenius square is sum_{j=1}^n |u_j|^2.\", \"depends_on\": [\"D006\", \"D002\"], \"requires\": [], \"binders\": [{\"symbol\": \"x\", \"type\": \"point of V\"}, {\"symbol\": \"r\", \"type\": \"positive real\"}], \"objects\": [\"u_jj\", \"u_j\", \"n\"]}}, {\"pointer\": \"spec.json#/definitions/8\", \"record\": {\"id\": \"D009\", \"symbol\": \"e\", \"type\": \"function V×(0,∞)→R\", \"definition\": \"e(x,r)=|u_t(x,r)|^2+sum_{j=1}^n |u_j(x,r)|^2.\", \"depends_on\": [\"D003\", \"D005\", \"D002\"], \"requires\": [], \"binders\": [{\"symbol\": \"x\", \"type\": \"point of V\"}, {\"symbol\": \"r\", \"type\": \"positive real\"}], \"objects\": [\"u_t\", \"u_j\", \"n\"]}}, {\"pointer\": \"spec.json#/definitions/9\", \"record\": {\"id\": \"D010\", \"symbol\": \"e_t\", \"type\": \"function V×(0,∞)→R\", \"definition\": \"e_t(x,r)=∂_r e(x,r), with the total derivative convention of D003.\", \"depends_on\": [\"D009\"], \"requires\": [], \"binders\": [{\"symbol\": \"x\", \"type\": \"point of V\"}, {\"symbol\": \"r\", \"type\": \"positive real\"}], \"objects\": [\"e\"]}}, {\"pointer\": \"spec.json#/definitions/10\", \"record\": {\"id\": \"D011\", \"symbol\": \"A\", \"type\": \"function V×(0,∞)→R\", \"definition\": \"A(x,r)=u_t(x,r)·u_tt(x,r).\", \"depends_on\": [\"D003\", \"D004\", \"D002\"], \"requires\": [], \"binders\": [{\"symbol\": \"x\", \"type\": \"point of V\"}, {\"symbol\": \"r\", \"type\": \"positive real\"}], \"objects\": [\"u_t\", \"u_tt\"]}}, {\"pointer\": \"spec.json#/definitions/11\", \"record\": {\"id\": \"D012\", \"symbol\": \"B\", \"type\": \"family indexed by j=1,...,n of real functions V×(0,∞)\", \"definition\": \"B_j(x,r)=u_j(x,r)·u_jt(x,r). The symbol B denotes this whole family, not a bound constant.\", \"depends_on\": [\"D005\", \"D007\", \"D002\"], \"requires\": [], \"binders\": [{\"symbol\": \"j\", \"type\": \"integer with 1≤j≤n\"}, {\"symbol\": \"x\", \"type\": \"point of V\"}, {\"symbol\": \"r\", \"type\": \"positive real\"}], \"objects\": [\"u_j\", \"u_jt\", \"n\"]}}, {\"pointer\": \"spec.json#/definitions/12\", \"record\": {\"id\": \"D013\", \"symbol\": \"T\", \"type\": \"family indexed by j=1,...,n of real functions V×(0,∞)\", \"definition\": \"T_j(x,r)=u_t(x,r)·u_jj(x,r).\", \"depends_on\": [\"D003\", \"D006\", \"D002\"], \"requires\": [], \"binders\": [{\"symbol\": \"j\", \"type\": \"integer with 1≤j≤n\"}, {\"symbol\": \"x\", \"type\": \"point of V\"}, {\"symbol\": \"r\", \"type\": \"positive real\"}], \"objects\": [\"u_t\", \"u_jj\", \"n\"]}}, {\"pointer\": \"spec.json#/definitions/13\", \"record\": {\"id\": \"D014\", \"symbol\": \"g\", \"type\": \"family indexed by j=1,...,n of real functions V×(0,∞)\", \"definition\": \"g_j(x,r)=u_t(x,r)·u_j(x,r).\", \"depends_on\": [\"D003\", \"D005\", \"D002\"], \"requires\": [], \"binders\": [{\"symbol\": \"j\", \"type\": \"integer with 1≤j≤n\"}, {\"symbol\": \"x\", \"type\": \"point of V\"}, {\"symbol\": \"r\", \"type\": \"positive real\"}], \"objects\": [\"u_t\", \"u_j\", \"n\"]}}, {\"pointer\": \"spec.json#/definitions/14\", \"record\": {\"id\": \"D015\", \"symbol\": \"E\", \"type\": \"function (0,∞)→R\", \"definition\": \"For r>0, E(r)=∫_V e(x,r) dx, the finite Lebesgue integral; the required integrability guard is that x↦e(x,r) is integrable for every r>0.\", \"depends_on\": [\"D001\", \"D009\"], \"requires\": [\"N002\"], \"binders\": [{\"symbol\": \"r\", \"type\": \"positive real\"}], \"objects\": [\"e\", \"V\"]}}], \"has_more\": false, \"next_offset\": null}"}}
