const checks = [
["M001",6,"The NL statement preserves the nontrivially normed scalar field, normed ring and normed-algebra premises, both HasDerivAt premises, and the ordered product formula c'·d(x)+c(x)·d'. No commutativity or completeness was silently added or omitted.",["Mathlib/Analysis/Calculus/Deriv/Mul.lean:38-45","Mathlib/Analysis/Calculus/Deriv/Mul.lean:259-271"]],
